tool_input.command:
mkdir -p submission .tmp
# valid set
VALID="grocery travel salary rent other"
# Build clean CSV (header + valid rows) and rejected id list
head -1 data/events.csv > .tmp/valid.csv
awk -F, 'NR==1{next}
{
  amt=$4; cat=$5;
  ok=1;
  if(amt=="") ok=0;                       # rule 1: present
  else if(amt+0<0 || amt+0>10000) ok=0;   # rule 2: range
  if(cat!="grocery"&&cat!="travel"&&cat!="salary"&&cat!="rent"&&cat!="other") ok=0; # rule 3
  if(ok==1) print $0 >> ".tmp/valid.csv";
  else print $1;
}' data/events.csv > .tmp/rejected.txt
echo "valid rows (excl header): $(($(wc -l < .tmp/valid.csv)-1))"
echo "rejected count: $(wc -l < .tmp/rejected.txt)"
echo "--- sample rejected ---"; head .tmp/rejected.txt

